var ZAI_ANTHROPIC_BASE_URL = "https://api.z.ai/api/anthropic";
function inferSalesLlmProvider(model) {
  const id = normalizeSalesModelId(model).toLowerCase();
  if (id.startsWith("gpt-") || /^o\d/.test(id) || id.startsWith("openai:")) return "openai";
  if (id.startsWith("glm-")) return "zai";
  return "anthropic";
}
function openAiLengthParams(modelId, maxTokens, temperature) {
  if (/^gpt-(6|5\.[1-9])/i.test(modelId)) {
    return { max_completion_tokens: maxTokens, reasoning_effort: "none" };
  }
  return { max_tokens: maxTokens, ...temperature != null ? { temperature } : {} };
}
function normalizeSalesModelId(model) {
  return String(model ?? "").trim().replace(/^zai:/i, "").replace(/^openai:/i, "");
}
