function chatPrepErrorResponse(error) {
  const message = error instanceof Error ? error.message : "Unknown error";
  const code = error.code;
  if (message === "Site not found") {
    return jsonResponse({ success: false, error: message }, 404);
  }
  if (code === "DISABLED") {
    return jsonResponse({ success: false, error: message, code: "DISABLED" }, 403);
  }
  if (message === "message is required") {
    return jsonResponse({ success: false, error: message }, 400);
  }
  return null;
}
async function handleChat(supabase, input) {
  let prepared;
  try {
    prepared = await prepareChat(supabase, input);
  } catch (error) {
    const prepResponse = chatPrepErrorResponse(error);
    if (prepResponse) return prepResponse;
    throw error;
  }
  const { site, message, systemPrompt, conversationMessages, nextUserSequence, nextAssistantSequence, routePath, knowledgeBase } = prepared;
  const client = requireSalesLlmClient(String(site.model));
  const toolContext = {
    supabase,
    siteId: input.siteId,
    sessionId: input.sessionId,
    siteMarkdown: knowledgeBase.siteMarkdown,
    shopMarkdown: knowledgeBase.shopMarkdown,
    routePath
  };
  const { text: aiResponse } = client.provider === "openai" ? await runVisitorLoopOpenAi({
    client,
    maxTokens: Number(site.max_tokens),
    systemPrompt,
    messages: conversationMessages,
    executeTool: (name, toolInput) => executeVisitorTool(name, toolInput, toolContext)
  }) : await runAnthropicToolLoop({
    apiKey: client.apiKey,
    model: client.modelId,
    // Claude or Z.ai (GLM): each has its own Messages endpoint.
    provider: client.provider === "zai" ? "zai" : "anthropic",
    messagesUrl: client.messagesUrl,
    // Visitors want a quick answer — the visitor chat always runs at low effort.
    effort: FIXED_LOW_EFFORT,
    maxTokens: Number(site.max_tokens),
    systemPrompt,
    messages: conversationMessages,
    tools: [...VISITOR_TOOL_DEFINITIONS],
    executeTool: (name, toolInput) => executeVisitorTool(name, toolInput, toolContext)
  });
  await persistConversation(supabase, {
    siteId: input.siteId,
    sessionId: input.sessionId,
    userMessage: message,
    assistantMessage: aiResponse,
    nextUserSequence,
    nextAssistantSequence,
    routePath
  });
  return jsonResponse({
    success: true,
    response: aiResponse,
    model: site.model
  });
}
async function handleChatStream(supabase, input) {
  let prepared;
  try {
    prepared = await prepareChat(supabase, input);
  } catch (error) {
    const prepResponse = chatPrepErrorResponse(error);
    if (prepResponse) return prepResponse;
    throw error;
  }
  const { site, message, systemPrompt, conversationMessages, nextUserSequence, nextAssistantSequence, routePath, knowledgeBase } = prepared;
  const stream = new ReadableStream({
    async start(controller) {
      const encoder = new TextEncoder();
      const send = (payload) => {
        controller.enqueue(encoder.encode(sseEvent(payload)));
      };
      let fullText = "";
      try {
        const client = requireSalesLlmClient(String(site.model));
        const toolContext = {
          supabase,
          siteId: input.siteId,
          sessionId: input.sessionId,
          siteMarkdown: knowledgeBase.siteMarkdown,
          shopMarkdown: knowledgeBase.shopMarkdown,
          routePath
        };
        const { text: aiResponse } = client.provider === "openai" ? await runVisitorLoopOpenAi({
          client,
          maxTokens: Number(site.max_tokens),
          systemPrompt,
          messages: conversationMessages,
          executeTool: (name, toolInput) => executeVisitorTool(name, toolInput, toolContext),
          onStatus: (status) => send({ type: "status", text: status }),
          onDelta: (text) => {
            fullText += text;
            send({ type: "text", text });
          }
        }) : await runAnthropicToolLoop({
          apiKey: client.apiKey,
          model: client.modelId,
          provider: client.provider === "zai" ? "zai" : "anthropic",
          messagesUrl: client.messagesUrl,
          effort: FIXED_LOW_EFFORT,
          maxTokens: Number(site.max_tokens),
          systemPrompt,
          messages: conversationMessages,
          tools: [...VISITOR_TOOL_DEFINITIONS],
          executeTool: (name, toolInput) => executeVisitorTool(name, toolInput, toolContext),
          onStatus: (status) => send({ type: "status", text: status }),
          onDelta: (text) => {
            fullText = text;
            send({ type: "text", text });
          }
        });
        fullText = aiResponse;
        if (!fullText.trim()) {
          send({ type: "error", error: "Empty response from model" });
          return;
        }
        await persistConversation(supabase, {
          siteId: input.siteId,
          sessionId: input.sessionId,
          userMessage: message,
          assistantMessage: fullText,
          nextUserSequence,
          nextAssistantSequence,
          routePath
        });
        send({ type: "done", model: site.model });
      } catch (error) {
        const errMessage = error instanceof Error ? error.message : "Unknown stream error";
        console.error("site-chat stream error:", errMessage);
        send({ type: "error", error: errMessage });
      } finally {
        controller.close();
      }
    }
  });
  return sseResponse(stream);
}
function openAiToolsFromVisitor() {
  return VISITOR_TOOL_DEFINITIONS.map((t) => ({
    type: "function",
    function: {
      name: t.name,
      description: t.description,
      parameters: t.input_schema
    }
  }));
}
function openAiMessages(systemPrompt, messages) {
  const mapped = [{ role: "system", content: systemPrompt }];
  for (const m of messages) {
    if (typeof m.content === "string") {
      mapped.push({ role: m.role, content: m.content });
    } else {
      mapped.push({ role: m.role, content: String(m.content ?? "") });
    }
  }
  return mapped;
}
async function runVisitorLoopOpenAi(input) {
  const tools = openAiToolsFromVisitor();
  const workingMessages = openAiMessages(input.systemPrompt, input.messages);
  let finalText = "";
  for (let round = 0; round < 4; round++) {
    const response = await fetch(input.client.chatCompletionsUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${input.client.apiKey}`
      },
      body: JSON.stringify({
        model: input.client.modelId,
        messages: workingMessages,
        tools,
        tool_choice: "auto",
        ...openAiLengthParams(input.client.modelId, input.maxTokens),
        stream: false
      })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      const errMessage = errorData?.error?.message ?? response.statusText;
      throw new Error(`${input.client.providerLabel} API error: ${errMessage}`);
    }
    const data = await response.json();
    const msg = data.choices?.[0]?.message ?? {};
    const toolCalls = msg.tool_calls ?? [];
    const text = (msg.content ?? "") || "";
    if (text) {
      finalText = text;
      if (input.onDelta && toolCalls.length === 0) input.onDelta(text);
    }
    if (!toolCalls.length) return { text: finalText };
    workingMessages.push({ role: "assistant", content: text || "", tool_calls: toolCalls });
    for (const call of toolCalls) {
      const toolName = call.function?.name ?? "";
      const rawArgs = call.function?.arguments ?? "{}";
      let args = {};
      try {
        args = JSON.parse(rawArgs);
      } catch {
        args = {};
      }
      input.onStatus?.(`Running ${toolName}\u2026`);
      const result = await input.executeTool(toolName, args);
      workingMessages.push({ role: "tool", tool_call_id: call.id, content: result });
    }
  }
  return { text: finalText || "I reached the tool limit for this turn. Please try a simpler request." };
}
